          ..write('trackUuid: $trackUuid, ')
          ..write('startedAt: $startedAt, ')
          ..write('durationSeconds: $durationSeconds, ')
          ..write('accumulatedMicros: $accumulatedMicros, ')
          ..write('lastCheckpointAt: $lastCheckpointAt, ')
          ..write('state: $state, ')
          ..write('finalPayloadJson: $finalPayloadJson, ')
          ..write('rowid: $rowid')
          ..write(')'))
